create or replace function public.bootstrap_workspace(workspace_name text) returns uuid language plpgsql security definer set search_path = public as $$ declare uid uuid := auth.uid(); wid uuid; begin if uid is null then raise exception 'Authentication required'; end if; select m.workspace_id into wid from public.workspace_memberships m where m.user_id=uid and m.status='active' order by m.created_at limit 1; if wid is not null then return wid; end if; insert into public.workspaces(name,created_by) values (coalesce(nullif(trim(workspace_name),''),'Ridgewood'),uid) returning id into wid; insert into public.workspace_memberships(workspace_id,user_id,technical_role,status) values(wid,uid,'owner','active'); return wid; end; $$; revoke all on function public.bootstrap_workspace(text) from public,anon; grant execute on function public.bootstrap_workspace(text) to authenticated;

drop policy if exists opportunities_select_workspace on public.opportunities; create policy opportunities_select_workspace on public.opportunities for select to authenticated using (workspace_id is not null and public.is_workspace_member(workspace_id));
drop policy if exists opportunities_insert_workspace on public.opportunities; create policy opportunities_insert_workspace on public.opportunities for insert to authenticated with check (workspace_id is not null and public.is_workspace_member(workspace_id) and owner_user_id=(select auth.uid()) and created_by=(select auth.uid()));
drop policy if exists opportunities_update_workspace on public.opportunities; create policy opportunities_update_workspace on public.opportunities for update to authenticated using (workspace_id is not null and public.is_workspace_member(workspace_id)) with check (workspace_id is not null and public.is_workspace_member(workspace_id));
